#!/usr/bin/env python3\n\"\"\"\nMinimální Python backend pro ChatBot-AI\nNapojuje se na lokální llama.cpp server a expozuje snadné API\n\nInstalace:\n  pip install flask requests python-dotenv\n\nSpuštění:\n  python backend-example.py\n\nNebo s CORS proxy pro vývoj:\n  pip install flask-cors\n\"\"\"\n\nimport os\nimport requests\nimport json\nfrom flask import Flask, request, jsonify\nfrom flask_cors import CORS\nfrom dotenv import load_dotenv\nimport logging\n\nload_dotenv()\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\napp = Flask(__name__)\nCORS(app)  # Povolte CORS pro frontend\n\n# Konfigurace\nLLAMA_SERVER_URL = os.getenv('LLAMA_SERVER_URL', 'http://localhost:8080')\nAPI_TIMEOUT = int(os.getenv('API_TIMEOUT', 60))\n\n# Parametry modelu\nDEFAULT_PARAMS = {\n    'n_predict': 150,\n    'temperature': 0.7,\n    'top_p': 0.9,\n    'top_k': 40,\n    'repeat_penalty': 1.1,\n}\n\n\n@app.route('/health', methods=['GET'])\ndef health():\n    \"\"\"Health check endpoint\"\"\"\n    try:\n        response = requests.get(f'{LLAMA_SERVER_URL}/health', timeout=2)\n        if response.status_code == 200:\n            return jsonify({'status': 'ok', 'backend': 'running'}), 200\n    except:\n        pass\n    return jsonify({'status': 'error', 'backend': 'unreachable'}), 503\n\n\n@app.route('/api/chat', methods=['POST'])\ndef chat():\n    \"\"\"\n    Hlavní endpoint pro chat\n    \n    Request JSON:\n    {\n      \"message\": \"Tvoje otázka\",\n      \"context\": [\"Předchozí zprávy opcionálně\"],\n      \"temperature\": 0.7,\n      \"max_tokens\": 150\n    }\n    \n    Response JSON:\n    {\n      \"reply\": \"Odpověď modelu\",\n      \"model\": \"Mistral 7B\",\n      \"timestamp\": \"2024-01-01T00:00:00Z\",\n      \"tokens_used\": 42\n    }\n    \"\"\"\n    try:\n        data = request.get_json()\n        \n        if not data or 'message' not in data:\n            return jsonify({'error': 'Missing message field'}), 400\n        \n        user_message = data['message'].strip()\n        if len(user_message) > 2000:\n            return jsonify({'error': 'Message too long (max 2000 chars)'}), 400\n        \n        # Sestrojte prompt s kontextem\n        context = data.get('context', [])\n        full_prompt = '\\n'.join(context) + f'\\nUživatel: {user_message}\\nAssistant:' if context else user_message\n        \n        # Získejte parametry\n        params = DEFAULT_PARAMS.copy()\n        if 'temperature' in data:\n            params['temperature'] = float(data['temperature'])\n        if 'max_tokens' in data:\n            params['n_predict'] = int(data['max_tokens'])\n        \n        # Zavolejte llama.cpp server\n        logger.info(f'Forwarding to llama.cpp: {full_prompt[:50]}...')\n        \n        response = requests.post(\n            f'{LLAMA_SERVER_URL}/v1/completions',\n            json={\n                'prompt': full_prompt,\n                **params,\n            },\n            timeout=API_TIMEOUT,\n        )\n        \n        if response.status_code != 200:\n            logger.error(f'Backend error: {response.status_code}')\n            return jsonify({'error': 'Backend error'}), 500\n        \n        result = response.json()\n        reply = result['choices'][0]['text'].strip()\n        \n        return jsonify({\n            'reply': reply,\n            'model': os.getenv('MODEL_NAME', 'GGUF Model'),\n            'tokens_used': result.get('usage', {}).get('completion_tokens', 0),\n        }), 200\n        \n    except requests.exceptions.Timeout:\n        return jsonify({'error': 'Backend timeout'}), 504\n    except requests.exceptions.ConnectionError:\n        return jsonify({'error': 'Cannot connect to backend'}), 503\n    except json.JSONDecodeError:\n        return jsonify({'error': 'Invalid JSON response from backend'}), 500\n    except Exception as e:\n        logger.error(f'Unexpected error: {str(e)}')\n        return jsonify({'error': 'Internal server error'}), 500\n\n\n@app.route('/api/models', methods=['GET'])\ndef list_models():\n    \"\"\"Vrátí seznam dostupných modelů (future feature)\"\"\"\n    return jsonify({\n        'models': [\n            {'name': 'default', 'size': '7B', 'quantization': 'Q4_K_M'}\n        ]\n    }), 200\n\n\nif __name__ == '__main__':\n    logger.info(f'Connecting to llama.cpp at {LLAMA_SERVER_URL}')\n    print('\\n🤖 ChatBot-AI Backend')\n    print(f'   Serving at http://0.0.0.0:5000')\n    print(f'   Forwarding to llama.cpp at {LLAMA_SERVER_URL}')\n    print('   Press Ctrl+C to stop\\n')\n    \n    app.run(host='0.0.0.0', port=5000, debug=False)\n"